"use strict";
let mobileWebSkin='uc';try{const v=localStorage.getItem('olddays-mobile-web-skin');if(['uc','opera'].includes(v))mobileWebSkin=v;}catch{}
function mobileWebMarkup(){const opera=mobileWebSkin==='opera';const links=[['news','新闻'],['books','小说'],['community','论坛'],['games','游戏'],['music','音乐'],['videos','视频'],['magazines','报刊'],['gallery','图文'],['comics','漫画']];return '<section class="mobile-web-site skin-'+mobileWebSkin+'"><header><b>'+(opera?'O':'UC')+'</b><span>'+(opera?'Opera Mini':'UC 浏览器')+'<small>旧日重制 / '+year()+'</small></span><button data-mobile-web-skin="'+(opera?'uc':'opera')+'">换成 '+(opera?'UC':'Opera')+'</button></header><form data-uc-search class="mobile-web-address"><input name="query" aria-label="手机地址或站内搜索" placeholder="搜网站、小说、新闻" value="'+escapeHTML(ucQuery)+'"><button>转到</button></form><nav><button data-uc-back>⌂ 首页</button><button data-uc-tab="nav">网址导航</button><button data-uc-tab="saved">书签</button></nav><div class="mobile-web-page">'+(ucContent?'<button data-uc-back>‹ 返回导航</button>'+ucRenderedContent():ucPage==='nav'?ucWebsiteDirectory():ucPage==='saved'?'<h2>本机书签</h2><p>从站点页添加收藏后，可在主菜单的“我的收藏”中查看。</p><button data-action="favorites">打开我的收藏 →</button>':'<div class="mobile-web-banner">欢迎来到 '+year()+' 年的掌上互联网<br><small>网速很慢，期待很长。</small></div><div class="mobile-web-grid">'+links.filter(([,t])=>!ucQuery||t.includes(ucQuery)).map(([id,t],i)=>'<button data-uc-open="'+id+'"><b>'+['报','书','聊','✣','♫','▶','刊','图','漫'][i]+'</b>'+t+'</button>').join('')+'</div><h2>热门网址</h2>'+ucWebsiteDirectory())+'</div><footer><button data-uc-back>‹ 返回首页</button><span>'+(opera?'Opera Mini':'UC')+' · 本机重制</span><button data-action="settings">菜单</button></footer></section>';}
const mobileWebPcBase=renderPcWorkbench,mobileWebBrowserBase=phoneUCMarkup;
renderPcWorkbench=function(){if(window.innerWidth<=650){phoneWebLayout='mobile';return mobileWebMarkup();}return mobileWebPcBase();};
phoneUCMarkup=function(){if(typeof experienceZone!=='undefined'&&experienceZone==='pc'&&window.innerWidth<=650)return mobileWebMarkup();const markup=mobileWebBrowserBase();return typeof experienceZone!=='undefined'&&experienceZone==='phone'&&phoneState.app==='browser'?'<div class="mobile-native-browser skin-'+mobileWebSkin+'"><button class="mobile-native-skin" data-mobile-web-skin="'+(mobileWebSkin==='uc'?'opera':'uc')+'">画风：'+(mobileWebSkin==='uc'?'UC':'Opera Mini')+' · 切换</button>'+markup.replace('优视浏览器',mobileWebSkin==='uc'?'UC 浏览器':'Opera Mini').replace('<b>UC</b>',mobileWebSkin==='uc'?'<b>UC</b>':'<b>O</b>')+'</div>':markup;};
document.addEventListener('click',e=>{const b=e.target.closest('[data-mobile-web-skin]');if(!b)return;const skin=b.getAttribute('data-mobile-web-skin');if(!['uc','opera'].includes(skin))return;e.preventDefault();mobileWebSkin=skin;try{localStorage.setItem('olddays-mobile-web-skin',skin);}catch{}if(experienceZone==='pc')navigate({type:'home'},false);else refreshPhone();});
let mobileWebWidth=window.innerWidth<=650;window.addEventListener('resize',()=>{const narrow=window.innerWidth<=650;if(narrow===mobileWebWidth)return;mobileWebWidth=narrow;if(experienceZone==='pc')navigate({type:'home'},false);});
const mobileWebRefreshBase=refreshPhone;
refreshPhone=function(){if(experienceZone==='pc'&&window.innerWidth<=650){savePhone();return navigate({type:'home'},false);}return mobileWebRefreshBase();};
